export function validateDIGESTIVELOWERSeed(): void {
  const slugs = new Set(
    DIGESTIVE_LOWER_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== DIGESTIVE_LOWER_STRUCTURES.length) {
    throw new Error(
      'Digestive system - lower tract seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    DIGESTIVE_LOWER_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== DIGESTIVE_LOWER_STRUCTURES.length) {
    throw new Error(
      'Digestive system - lower tract seed contains duplicate mesh names.',
    );
  }
  if (DIGESTIVE_LOWER_STRUCTURES.length !== 19) {
    throw new Error(
      'Digestive system - lower tract seed must contain exactly 19 structures.',
    );
  }
  for (const structure of DIGESTIVE_LOWER_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
